/// Cleared by [`cleanup_client`]; gates the frame hook and background loops.
pub static RUNNING: AtomicBool = AtomicBool::new(false);

/// Entry point the agent loader calls once the library is loaded — the
/// [`client_abi::StartFn`] contract. The Minecraft version is checked here,
/// synchronously, so the agent can tell the injector whether the client
/// actually started; the rest of the startup runs on its own thread.
///
/// # Safety
/// `report` must be valid for writes of `capacity` bytes, or null.
#[no_mangle]
pub unsafe extern "C" fn start_client(force: bool, report: *mut u8, capacity: usize) -> i32 {
    let (status, message) = start(force);
    write_report(report, capacity, &message);
    status
}

// Keep the exports in lockstep with what the agent loader expects.
const _: client_abi::StartFn = start_client;
const _: client_abi::CleanupFn = cleanup_client;

/// Brings the client up; returns the [`client_abi`] status and the report —
/// the Minecraft version id, or why it could not start.
fn start(force: bool) -> (i32, String) {
    if RUNNING.swap(true, Ordering::SeqCst) {
        return (
            client_abi::FAILED,
            "the client is already running".to_string(),
        );
    }

    // The log lives alongside the config, in the injector's directory — never
    // in `.minecraft` — see `config::base_dir`.
    let log_path = config::base_dir().join("dark_client.log");
    match File::create(&log_path) {
        Ok(file) => {
            if let Err(e) = WriteLogger::init(LevelFilter::Debug, Config::default(), file) {
                eprintln!("Error during logger initialization: {e:?}");
            }
        }
        Err(e) => eprintln!("Could not create {}: {e}", log_path.display()),
    }
    info!("Starting DarkClient…");

    // Custom panic hook: guarantee the input / render hooks are released.
    let default_hook = std::panic::take_hook();
    std::panic::set_hook(Box::new(move |panic_info| {
        error!("DarkClient panicked! Restoring input/render hooks…");
        cleanup_client();
        default_hook(panic_info);
    }));

    let runtime = match state::init_runtime() {
        Ok(runtime) => runtime,
        Err(e) => {
            error!("Client initialization failed: {e}");
            RUNNING.store(false, Ordering::SeqCst);
            return (client_abi::FAILED, e.to_string());
        }
    };

    let version = runtime.version_id().unwrap_or("unknown").to_string();
    if !runtime.version_id().is_some_and(mc_versions::is_supported) {
        let supported = mc_versions::SUPPORTED_VERSIONS.join(", ");
        if !force {
            warn!("Minecraft {version} is not supported (supported: {supported}); not starting");
            RUNNING.store(false, Ordering::SeqCst);
            return (client_abi::UNSUPPORTED, version);
        }
        warn!("Minecraft {version} is not supported (supported: {supported}); starting anyway, forced");
    }

    thread::spawn(|| {
        // Fixed, straight-line startup order: build the game state, then
        // register modules, then install the hooks last so the frame hook
        // never observes an uninitialized client.
        if let Err(e) = state::init_client() {
            error!("Client initialization failed: {e}");
            return;
        }
        register_modules();
        // Restore saved keybinds, settings and enabled state.
        config::load();
        if let Err(e) = install_hooks() {
            error!("Failed to install hooks: {e}");
        }
        info!("DarkClient started");
        self_check();
    });

    (client_abi::STARTED, version)
}

/// Logs any binding the running game lacks: the modules using it would fail.
fn self_check() {
    let started = std::time::Instant::now();
    let report = match mc_bindings::verify() {
        Ok(report) => report,
        Err(e) => {
            warn!("Binding self-check could not run: {e}");
            return;
        }
    };
    let elapsed = started.elapsed();
    if !report.absent.is_empty() {
        info!("Not in this build, skipped: {}", report.absent.join(", "));
    }
    if report.missing.is_empty() {
        info!(
            "Binding self-check: all {} bindings resolve ({elapsed:.0?})",
            report.checked
        );
        return;
    }
    for missing in &report.missing {
        warn!("Binding self-check: missing {missing}");
    }
    warn!(
        "Binding self-check: {} of {} bindings missing ({elapsed:.0?})",
        report.missing.len(),
        report.checked
    );
}

/// Copies `message` into the agent's report buffer as a NUL-terminated
/// string, truncated on a character boundary to fit.
///
/// # Safety
/// `report` must be valid for writes of `capacity` bytes, or null.
unsafe fn write_report(report: *mut u8, capacity: usize, message: &str) {
    if report.is_null() || capacity == 0 {
        return;
    }
    let mut len = message.len().min(capacity - 1);
    while !message.is_char_boundary(len) {
        len -= 1;
    }
    std::ptr::copy_nonoverlapping(message.as_ptr(), report, len);
    *report.add(len) = 0;
}

/// Cleanup entry point called by the agent loader before unload.
#[no_mangle]
pub extern "C" fn cleanup_client() {
    info!("Client cleanup in progress…");
    RUNNING.store(false, Ordering::SeqCst);
    uninstall_hooks();
    crate::graphic::input::cleanup();
    // Stop every still-active enabled module before the JNI runtime is torn
    // down — without this, hot-reloading the library would leak whatever
    // state the active modules installed (camera handles, packet listeners,
    // overridden game modes, …) until the user toggled them off by hand.
    // Guarded with `try_client` because the panic hook may reach here before
    // `init` had a chance to succeed.
    if let Some(client) = crate::state::try_client() {
        client.modules.set_active(false);
    }
    // Hooks are gone and `RUNNING` is clear, so nothing else touches the
    // global state — release the JVM references it holds before unload.
    crate::state::teardown();
    info!("Client cleanup completed");
}

/// Registers the built-in modules with the client.
fn register_modules() {
    let modules = &client().modules;
    modules.register(FlyModule::new());
    modules.register(NoFallModule::new());
    modules.register(KillAuraModule::new());
    modules.register(MobAuraModule::new());
    modules.register(AimbotModule::new());
    modules.register(CriticalsModule::new());
    modules.register(VelocityModule::new());
    modules.register(PlayerEspModule::new());
    modules.register(MobEspModule::new());
    modules.register(ChestEspModule::new());
    modules.register(TracersModule::new());
    modules.register(FullbrightModule::new());
    modules.register(AntiAfkModule::new());
    modules.register(SprintModule::new());
    modules.register(NametagsModule::new());
    modules.register(SpeedModule::new());
    modules.register(NoSlowdownModule::new());
    modules.register(AutoTotemModule::new());
    modules.register(ChestStealerModule::new());
    modules.register(AutoArmorModule::new());
    modules.register(NukerModule::new());
    modules.register(ScaffoldModule::new());
    modules.register(FreecamModule::new());
    modules.register(ArrayListModule::new());
}
